import { jest } from '@jest/globals';

const mockGetInput = jest.fn();
const mockGetBooleanInput = jest.fn();

jest.unstable_mockModule('@actions/core', () => ({
  getInput: mockGetInput,
  getBooleanInput: mockGetBooleanInput,
}));

const { readInputs } = await import('../src/inputs.js');

describe('readInputs', () => {
  beforeEach(() => {
    mockGetInput.mockImplementation((name) => {
      if (name === 'file-paths') {
        return 'coverage/lcov.info';
      }
      if (name === 'region') {
        return '';
      }
      return '';
    });
    mockGetBooleanInput.mockReturnValue(true);
  });

  it('reads action inputs', () => {
    expect(readInputs()).toEqual({
      filePaths: ['coverage/lcov.info'],
      failOnError: true,
      region: 'eu',
    });
    expect(mockGetInput).toHaveBeenCalledWith('file-paths', {
      required: true,
      trimWhitespace: true,
    });
    expect(mockGetInput).toHaveBeenCalledWith('region', {
      required: false,
      trimWhitespace: true,
    });
    expect(mockGetBooleanInput).toHaveBeenCalledWith('fail-on-error');
  });

  it('reads an explicit region', () => {
    mockGetInput.mockImplementation((name) => {
      if (name === 'file-paths') {
        return 'coverage/lcov.info';
      }
      if (name === 'region') {
        return 'us';
      }
      return '';
    });

    expect(readInputs().region).toBe('us');
  });

  it.each([
    ['newlines', 'packages/a/coverage/lcov.info\npackages/b/coverage/lcov.info'],
    ['commas', 'packages/a/coverage/lcov.info,packages/b/coverage/lcov.info'],
    ['spaces', 'packages/a/coverage/lcov.info packages/b/coverage/lcov.info'],
  ])('splits file paths on %s', (_label, input) => {
    mockGetInput.mockImplementation((name) => {
      if (name === 'file-paths') {
        return input;
      }
      return '';
    });

    expect(readInputs().filePaths).toEqual([
      'packages/a/coverage/lcov.info',
      'packages/b/coverage/lcov.info',
    ]);
  });
});

import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { resolveInputFilePatterns } from '../src/resolveInputFilePatterns.js';

describe('resolveInputFilePatterns', () => {
  let tmpDir;
  let previousCwd;

  beforeEach(async () => {
    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'resolve-patterns-'));
    previousCwd = process.cwd();
    process.chdir(tmpDir);
  });

  afterEach(async () => {
    process.chdir(previousCwd);
    await fs.rm(tmpDir, { recursive: true, force: true });
  });

  it('resolves a literal path', async () => {
    await fs.writeFile('lcov.info', '');

    const resolved = await resolveInputFilePatterns(['lcov.info']);

    expect(resolved).toEqual(['lcov.info']);
  });

  it('expands a glob pattern to every matching file', async () => {
    await fs.mkdir('packages/a/coverage', { recursive: true });
    await fs.mkdir('packages/b/coverage', { recursive: true });
    await fs.writeFile('packages/a/coverage/lcov.info', '');
    await fs.writeFile('packages/b/coverage/lcov.info', '');

    const resolved = await resolveInputFilePatterns(['packages/*/coverage/lcov.info']);

    expect(resolved.sort()).toEqual(
      ['packages/a/coverage/lcov.info', 'packages/b/coverage/lcov.info'].sort(),
    );
  });

  it('deduplicates files matched by overlapping patterns', async () => {
    await fs.mkdir('coverage', { recursive: true });
    await fs.writeFile('coverage/lcov.info', '');

    const resolved = await resolveInputFilePatterns(['coverage/lcov.info', 'coverage/*.info']);

    expect(resolved).toEqual(['coverage/lcov.info']);
  });

  it('throws when a pattern matches no files', async () => {
    await expect(resolveInputFilePatterns(['packages/*/coverage/lcov.info'])).rejects.toThrow(
      /No file\(s\) found matching "packages\/\*\/coverage\/lcov.info"/,
    );
  });

  it('rejects an absolute pattern', async () => {
    await expect(resolveInputFilePatterns(['/etc/passwd'])).rejects.toThrow(
      /Invalid file path: absolute paths and "\.\." segments are not allowed/,
    );
  });

  it('rejects a pattern containing ".." segments', async () => {
    await expect(resolveInputFilePatterns(['../etc/passwd'])).rejects.toThrow(
      /Invalid file path: absolute paths and "\.\." segments are not allowed/,
    );
  });

  it('rejects a matched file that is a symlink outside the workspace', async () => {
    const secret = await fs.mkdtemp(path.join(os.tmpdir(), 'resolve-patterns-secret-'));
    await fs.writeFile(path.join(secret, 'passwd'), 'root:x:0:0');
    await fs.symlink(path.join(secret, 'passwd'), 'coverage.info');

    try {
      await expect(resolveInputFilePatterns(['coverage.info'])).rejects.toThrow(
        /matched a symlink, which is not allowed/,
      );
    } finally {
      await fs.rm(secret, { recursive: true, force: true });
    }
  });
});

import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { collectUploadPayload } from '../src/collectUploadPayload.js';

describe('collectUploadPayload', () => {
  let tmpDir;

  beforeEach(async () => {
    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'collect-payload-'));
    await fs.mkdir(path.join(tmpDir, '.git'), { recursive: true });
    await fs.mkdir(path.join(tmpDir, 'src'), { recursive: true });
    await fs.writeFile(path.join(tmpDir, 'src/app.js'), 'line1\nline2\nline3\n');
  });

  afterEach(async () => {
    await fs.rm(tmpDir, { recursive: true, force: true });
  });

  it('builds repository_source_paths, eof, and files from coverage inputs', async () => {
    const previousCwd = process.cwd();
    process.chdir(tmpDir);
    process.env.GITHUB_WORKSPACE = tmpDir;

    try {
      const lcov = 'SF:src/app.js\nDA:1,1\nend_of_record\n';
      await fs.writeFile('coverage.lcov', lcov);

      const payload = await collectUploadPayload(['coverage.lcov']);

      expect(payload.repository_source_paths).toContain('src/app.js');
      expect(payload.eof['src/app.js']).toBe(4);
      expect(payload.files).toEqual([
        {
          filename: 'coverage.lcov',
          format: 'lcov',
          content: lcov,
        },
      ]);
    } finally {
      process.chdir(previousCwd);
    }
  });

  it('rejects empty file path list', async () => {
    await expect(collectUploadPayload([])).rejects.toThrow(/No code coverage file/);
  });
});

import { jest } from '@jest/globals';
import { mkdtemp, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { gunzipSync } from 'node:zlib';

const mockPost = jest.fn();
const mockHttpClient = jest.fn();
const mockGetIDToken = jest.fn();
const mockSetSecret = jest.fn();

jest.unstable_mockModule('@actions/core', () => ({
  getIDToken: [REDACTED],
  setSecret: [REDACTED],
}));

jest.unstable_mockModule('@actions/http-client', () => ({
  HttpClient: mockHttpClient,
  HttpCodes: {
    OK: 200,
  },
}));

const { getAuthHeaders, getBaseUrl, uploadCoverage } = await import('../src/aikido.js');

function mockResponse(statusCode, rawBody = '') {
  return {
    message: { statusCode },
    readBody: jest.fn().mockResolvedValue(rawBody),
  };
}

function decodeCoverageContent(encoded) {
  return gunzipSync(Buffer.from(encoded, 'base64')).toString('utf8');
}

function samplePayload(content = 'TN:\nSF:a\nend_of_record\n', format = 'lcov') {
  return {
    repository_source_paths: ['src/a.js'],
    eof: { 'src/a.js': 3 },
    files: [{ filename: 'lcov.info', format, content }],
  };
}

describe('getBaseUrl', () => {
  beforeEach(() => {
    delete process.env.DEVELOPMENT;
  });

  it.each([
    ['', 'https://bg.aikido.dev'],
    ['eu', 'https://bg.aikido.dev'],
    ['EU', 'https://bg.aikido.dev'],
    ['us', 'https://bg.us.aikido.dev'],
    ['au', 'https://bg.au.aikido.dev'],
    ['us-gov', 'https://bg.aikidogov.us'],
  ])('maps region %j to %s', (region, url) => {
    expect(getBaseUrl(region)).toBe(url);
  });

  it('throws for an unknown region', () => {
    expect(() => getBaseUrl('mars')).toThrow(
      'Unknown region "mars". Supported regions: eu, us, au, us-gov',
    );
  });

  it('uses the development URL when DEVELOPMENT is set', () => {
    process.env.DEVELOPMENT = 'true';
    expect(getBaseUrl('us')).toBe('https://app.test.aikido.dev');
  });
});

describe('getAuthHeaders', () => {
  beforeEach(() => {
    delete process.env.DEVELOPMENT;
    mockGetIDToken.mockReset();
    mockSetSecret.mockReset();
  });

  it('returns a bearer token and masks it', async () => {
    mockGetIDToken.mockResolvedValue('oidc-jwt');

    await expect(getAuthHeaders()).resolves.toEqual({
      Authorization: 'Bearer oidc-jwt',
    });
    expect(mockGetIDToken).toHaveBeenCalledWith('https://bg.aikido.dev');
    expect(mockSetSecret).toHaveBeenCalledWith('oidc-jwt');
  });

  it('uses the region base URL as the OIDC audience', async () => {
    mockGetIDToken.mockResolvedValue('oidc-jwt');

    await getAuthHeaders('us');

    expect(mockGetIDToken).toHaveBeenCalledWith('https://bg.us.aikido.dev');
  });

  it('throws a friendly error when OIDC is unavailable', async () => {
    mockGetIDToken.mockRejectedValue(new Error('OIDC not available'));

    await expect(getAuthHeaders()).rejects.toThrow(
      'This action uses OIDC to authenticate with Aikido. Add to your workflow job:\n  permissions:\n    id-token: write',
    );
  });

  it('rethrows unknown region errors', async () => {
    await expect(getAuthHeaders('mars')).rejects.toThrow('Unknown region "mars"');
    expect(mockGetIDToken).not.toHaveBeenCalled();
  });
});

describe('uploadCoverage', () => {
  let eventDir;

  beforeEach(() => {
    process.env.GITHUB_REPOSITORY = 'org/repo';
    process.env.GITHUB_SHA = 'abc123';
    process.env.GITHUB_HEAD_REF = 'main';
    delete process.env.GITHUB_EVENT_NAME;
    delete process.env.GITHUB_EVENT_PATH;
    delete process.env.DEVELOPMENT;
    mockHttpClient.mockImplementation(() => ({
      post: mockPost,
    }));
    mockPost.mockResolvedValue(mockResponse(200, JSON.stringify({ success: true })));
    mockGetIDToken.mockResolvedValue('oidc-jwt');
    mockSetSecret.mockReset();
  });

  afterEach(async () => {
    if (eventDir) {
      await rm(eventDir, { recursive: true, force: true });
      eventDir = undefined;
    }
  });

  async function writeEventPayload(payload) {
    eventDir = await mkdtemp(path.join(tmpdir(), 'aikido-event-'));
    const eventPath = path.join(eventDir, 'event.json');
    await writeFile(eventPath, JSON.stringify(payload));
    process.env.GITHUB_EVENT_PATH = eventPath;
  }

  it('posts files, repository_source_paths, and eof with a bearer token', async () => {
    const payload = samplePayload();
    const result = await uploadCoverage(payload);

    expect(result).toEqual({ success: true });
    expect(mockGetIDToken).toHaveBeenCalledWith('https://bg.aikido.dev');
    expect(mockSetSecret).toHaveBeenCalledWith('oidc-jwt');
    expect(mockHttpClient).toHaveBeenCalledWith('aikido-code-coverage');
    expect(mockPost).toHaveBeenCalledTimes(1);
    const [url, rawBody, headers] = mockPost.mock.calls[0];
    expect(url).toBe(
      'https://bg.aikido.dev/api/integrations/continuous_integration/scan/code_coverage',
    );
    const body = JSON.parse(rawBody);
    expect(body.repo_name).toBe('org/repo');
    expect(body.commit_sha).toBe('abc123');
    expect(body.branch_name).toBe('main');
    expect(body.repository_source_paths).toEqual(['src/a.js']);
    expect(body.eof).toEqual({ 'src/a.js': 3 });
    expect(body.files).toHaveLength(1);
    expect(body.files[0].filename).toBe('lcov.info');
    expect(body.files[0].format).toBe('lcov');
    expect(decodeCoverageContent(body.files[0].content)).toBe(payload.files[0].content);
    expect(body.code_coverage_file_content).toBeUndefined();
    expect(body.format).toBeUndefined();
    expect(headers).toEqual({
      Authorization: 'Bearer oidc-jwt',
      'Content-Type': 'application/json',
      Accept: 'application/json',
    });
  });

  /**
   * Aikido's PR coverage check looks up snapshots by related_commit_sha = PR head.
   * On pull_request, GITHUB_SHA is a temporary merge commit — uploading that SHA
   * never attaches to the open check. Regression: commit_sha must be head.sha.
   */
  it('uploads PR head SHA so coverage attaches to the open PR check', async () => {
    const mergeSha = 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';
    const prHeadSha = 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb';

    process.env.GITHUB_SHA = mergeSha;
    process.env.GITHUB_EVENT_NAME = 'pull_request';
    await writeEventPayload({
      pull_request: { head: { sha: prHeadSha } },
    });

    await uploadCoverage(samplePayload());

    const body = JSON.parse(mockPost.mock.calls[0][1]);
    expect(body.commit_sha).toBe(prHeadSha);
    expect(body.commit_sha).not.toBe(mergeSha);
  });

  it('uploads GITHUB_SHA on push events', async () => {
    process.env.GITHUB_SHA = 'push-commit-sha';
    process.env.GITHUB_EVENT_NAME = 'push';
    await writeEventPayload({ after: 'push-commit-sha' });

    await uploadCoverage(samplePayload());

    const body = JSON.parse(mockPost.mock.calls[0][1]);
    expect(body.commit_sha).toBe('push-commit-sha');
  });

  it('posts cobertura files when format is cobertura', async () => {
    const xml = '<coverage/>';
    await uploadCoverage(samplePayload(xml, 'cobertura'));

    const [, rawBody] = mockPost.mock.calls[0];
    const body = JSON.parse(rawBody);
    expect(body.files[0].format).toBe('cobertura');
    expect(decodeCoverageContent(body.files[0].content)).toBe(xml);
  });

  it('throws with reason_phrase from the JSON body', async () => {
    mockPost.mockResolvedValue(
      mockResponse(
        401,
        JSON.stringify({ status_code: 401, reason_phrase: 'OIDC token audience mismatch.' }),
      ),
    );

    await expect(uploadCoverage(samplePayload())).rejects.toThrow(
      'Aikido upload failed: Request failed with status code 401 - OIDC token audience mismatch.',
    );
  });

  it('throws with the API message when reason_phrase is absent', async () => {
    mockPost.mockResolvedValue(mockResponse(401, JSON.stringify({ message: 'Invalid API key' })));

    await expect(uploadCoverage(samplePayload())).rejects.toThrow(
      'Aikido upload failed: Request failed with status code 401 - Invalid API key',
    );
  });

  it('throws with the raw body when JSON has no known error fields', async () => {
    mockPost.mockResolvedValue(mockResponse(401, JSON.stringify({ unexpected: true })));

    await expect(uploadCoverage(samplePayload())).rejects.toThrow(
      'Aikido upload failed: Request failed with status code 401 - {"unexpected":true}',
    );
  });

  it('throws with the status code when the response body is empty', async () => {
    mockPost.mockResolvedValue(mockResponse(401, ''));

    await expect(uploadCoverage(samplePayload())).rejects.toThrow(
      'Aikido upload failed: Request failed with status code 401',
    );
  });

  it('throws with the raw body when the response is not JSON', async () => {
    mockPost.mockResolvedValue(mockResponse(500, 'Internal server error'));

    await expect(uploadCoverage(samplePayload())).rejects.toThrow(
      'Aikido upload failed: Request failed with status code 500 - Internal server error',
    );
  });
});

import { applySourceLineFixes, loadSourceLineFixes } from '../src/sourceLineFixes.js';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';

describe('sourceLineFixes', () => {
  let tmpDir;

  beforeEach(async () => {
    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'source-fixes-'));
  });

  afterEach(async () => {
    await fs.rm(tmpDir, { recursive: true, force: true });
  });

  it('reports eof for any source language without content-based ignores', async () => {
    const source = ['function x() {', '  return 1;', '}', '', '// done', ''].join('\n');
    await fs.writeFile(path.join(tmpDir, 'mod.js'), source);
    await fs.writeFile(path.join(tmpDir, 'mod.go'), source);
    await fs.writeFile(path.join(tmpDir, 'mod.py'), source);

    for (const relativePath of ['mod.js', 'mod.go', 'mod.py']) {
      const fixes = await loadSourceLineFixes(tmpDir, relativePath);
      expect(fixes.eof).toBe(6);
      expect(fixes.ignored).toBeUndefined();
    }
  });

  it('returns null when the source file is missing', async () => {
    expect(await loadSourceLineFixes(tmpDir, 'missing.ts')).toBeNull();
  });

  it('returns null for a tracked symlink instead of following it', async () => {
    const linkPath = path.join(tmpDir, 'generated.js');
    await fs.symlink('/dev/null', linkPath);

    expect(await loadSourceLineFixes(tmpDir, 'generated.js')).toBeNull();
  });

  it('drops DA, FN, and BRDA entries past eof', () => {
    const record = {
      sourcePath: 'mod.go',
      inputIndex: 0,
      lines: new Map([
        [1, 1],
        [2, 0],
        [3, 1],
        [9, 1],
      ]),
      functions: new Map([['x', { line: 9, hits: 1 }]]),
      branches: new Map([
        ['2\0\0\0', 1],
        ['9\0\0\0', 1],
      ]),
    };

    applySourceLineFixes(record, { eof: 3 });

    expect([...record.lines.keys()]).toEqual([1, 2, 3]);
    expect(record.functions.size).toBe(0);
    expect([...record.branches.keys()]).toEqual(['2\0\0\0']);
  });
});

import { detectFormatFromFilename, extractCoveredSourcePaths } from '../src/reportPaths.js';

describe('reportPaths', () => {
  describe('detectFormatFromFilename', () => {
    it('detects lcov from filename', () => {
      expect(detectFormatFromFilename('coverage/lcov.info')).toBe('lcov');
      expect(detectFormatFromFilename('out.lcov')).toBe('lcov');
      expect(detectFormatFromFilename('coverage\\lcov.info')).toBe('lcov');
    });

    it('detects cobertura from filename', () => {
      expect(detectFormatFromFilename('cobertura.xml')).toBe('cobertura');
      expect(detectFormatFromFilename('coverage/coverage.xml')).toBe('cobertura');
    });

    it('throws when format cannot be detected', () => {
      expect(() => detectFormatFromFilename('report.txt')).toThrow(
        /Could not detect coverage format/,
      );
    });
  });

  describe('extractCoveredSourcePaths', () => {
    const root = '/repo';

    it('extracts LCOV SF paths', () => {
      expect(
        extractCoveredSourcePaths(
          'SF:src/a.js\nDA:1,1\nend_of_record\nSF:src/b.js\nend_of_record\n',
          'lcov',
          root,
        ),
      ).toEqual(['src/a.js', 'src/b.js']);
    });

    it('relativizes absolute LCOV paths against the repository root', () => {
      expect(
        extractCoveredSourcePaths(`SF:${root}/src/a.js\nend_of_record\n`, 'lcov', root),
      ).toEqual(['src/a.js']);
    });

    it('extracts Cobertura filenames', () => {
      const xml = `<class name="a" filename="src/a.js"><lines/></class>`;
      expect(extractCoveredSourcePaths(xml, 'cobertura', root)).toEqual(['src/a.js']);
    });
  });
});

import { jest } from '@jest/globals';
