import { promises as fs } from 'node:fs';
import path from 'node:path';
import * as glob from '@actions/glob';
import { normalizePathSeparators, validateFilePath } from './paths.js';

/**
 * Expand glob patterns (and literal paths) to workspace-relative file paths.
 * Every pattern must match at least one file.
 */
export async function resolveInputFilePatterns(patterns) {
  const cwd = process.cwd();
  const resolvedPaths = [];

  for (const pattern of patterns) {
    validateFilePath(pattern);

    const globber = await glob.create(pattern, {
      followSymbolicLinks: false,
      matchDirectories: false,
    });
    const matches = await globber.glob();

    if (matches.length === 0) {
      throw new Error(`No file(s) found matching "${pattern}"`);
    }

    for (const match of matches.sort()) {
      const resolvedPath = path.resolve(match);
      const relativePath = normalizePathSeparators(path.relative(cwd, resolvedPath));
      validateFilePath(relativePath);

      // followSymbolicLinks: false above only stops glob from descending into
      // symlinked directories; it still returns a symlinked file as a match.
      // Reject those so collectUploadPayload cannot read outside the workspace.
      if ((await fs.lstat(resolvedPath)).isSymbolicLink()) {
        throw new Error(`Invalid file path: "${pattern}" matched a symlink, which is not allowed`);
      }

      resolvedPaths.push(relativePath);
    }
  }

  return [...new Set(resolvedPaths)];
}

import * as core from '@actions/core';
import { readInputs } from './inputs.js';
import { resolveInputFilePatterns } from './resolveInputFilePatterns.js';
import { collectUploadPayload } from './collectUploadPayload.js';
import { uploadCoverage } from './aikido.js';

async function run() {
  let failOnError = true;

  try {
    const inputs = readInputs();
    failOnError = inputs.failOnError;

    if (inputs.filePaths.length === 0) {
      throw new Error(`No code coverage file(s) provided. Specify at least one path.`);
    }

    const filePaths = await resolveInputFilePatterns(inputs.filePaths);

    core.info(
      `Found ${filePaths.length} coverage file(s) at path(s) \n\t${filePaths.join('\n\t')}`,
    );

    core.info('Collecting repository_source_paths and EOF metadata...');
    const payload = await collectUploadPayload(filePaths);

    core.info(
      `Uploading ${payload.files.length} coverage file(s) (repository_source_paths=${payload.repository_source_paths.length}, eof=${Object.keys(payload.eof).length}) for branch ${process.env.GITHUB_HEAD_REF || process.env.GITHUB_REF_NAME} to Aikido...`,
    );
    await uploadCoverage(payload, inputs.region);

    core.info(`Upload succeeded.`);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);

    if (failOnError) {
      core.setFailed(message);
    } else {
      core.warning(`Coverage upload skipped: ${message}`);
    }
  }
}

export { run };
run();

import { normalizePathSeparators, normalizeSourcePath } from './paths.js';

/**
 * Detect coverage format from the report filename only.
 * @param {string} filename
 * @returns {'lcov' | 'cobertura'}
 */
export function detectFormatFromFilename(filename) {
  const lower = normalizePathSeparators(filename).toLowerCase();
  const base = lower.slice(lower.lastIndexOf('/') + 1);

  if (base.endsWith('.lcov') || base.endsWith('.info') || base.includes('lcov')) {
    return 'lcov';
  }

  if (base.endsWith('.xml') || base.includes('cobertura')) {
    return 'cobertura';
  }

  throw new Error(
    `Could not detect coverage format from filename "${filename}". ` +
      'Use a name like lcov.info, *.lcov, or *cobertura*.xml.',
  );
}

/**
 * Extract source file paths referenced in a coverage report (for EOF map).
 * @param {string} content
 * @param {'lcov' | 'cobertura'} format
 * @param {string} repositoryRoot
 * @returns {string[]}
 */
export function extractCoveredSourcePaths(content, format, repositoryRoot) {
  if (format === 'cobertura') {
    return extractCoberturaFilenames(content, repositoryRoot);
  }

  return extractLcovFilenames(content, repositoryRoot);
}

function extractLcovFilenames(content, repositoryRoot) {
  return [...content.matchAll(/^SF:([^\r\n]+)$/gm)]
    .map((match) => normalizeSourcePath(match[1], repositoryRoot))
    .filter(Boolean);
}

function extractCoberturaFilenames(content, repositoryRoot) {
  const paths = [];
  for (const match of content.matchAll(/\bfilename\s*=\s*"([^"]+)"/gi)) {
    const normalized = normalizeSourcePath(match[1], repositoryRoot);
    if (normalized) {
      paths.push(normalized);
    }
  }

  return paths;
}
